scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var hits = new global.EcsPortability(new global.EcsAst(engine.rootNode)).userAndGroupNames();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CFG-004',
        title: 'Hardcoded user or group name',
        recommendation: 'Store the user or group in a system property (preferably its sys_id, set per environment) or resolve it through configuration such as an assignment rule, instead of naming it in the script.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
